// Autenticación: ¿quién sos? (una tabla de tokens de práctica)
app.use((req, res, next) => {
  const t = (req.headers.authorization || "").replace(/^Bearer /, "");
  req.usuario = usuarios[t];
  if (!req.usuario) return res.status(401).set("WWW-Authenticate", "Bearer").json({ error: "sin_sesion" });
  next();
});

app.get("/pedidos/:id", (req, res) => {
  const p = pedidos[req.params.id];
  if (!p) return res.status(404).json({ error: "no_existe" });
  res.json(p);            // ¿y si el pedido es de otra persona?
});

app.delete("/pedidos/:id", (req, res) => {
  const p = pedidos[req.params.id];
  if (!p) return res.status(404).json({ error: "no_existe" });
  delete pedidos[p.id];   // ¿y si quien borra es un cliente?
  res.json({ borrado: p.id });
});

app.patch("/perfil", (req, res) => {
  Object.assign(req.usuario, req.body);   // acepta cualquier campo que mande el cliente
  res.json(req.usuario);
});

// Una política de acceso en un solo lugar. Datos inventados.
const reglas = {
  "pedido:leer": (u, p) => u.rol === "admin" || p.dueno === u.id || (u.rol === "operador" && p.deposito === u.deposito),
  "pedido:borrar": (u, p) => u.rol === "admin" || (u.rol === "operador" && p.deposito === u.deposito && p.estado === "pendiente"),
};
// Lo que no está escrito se niega: acción desconocida => false.
const puede = (u, accion, p) => (reglas[accion] ? reglas[accion](u, p) === true : false);

const marta = { id: "marta", rol: "cliente" };
const lucho = { id: "lucho", rol: "operador", deposito: "norte" };
const dani = { id: "dani", rol: "admin" };
const p41 = { id: 41, dueno: "ana", deposito: "norte", estado: "en ruta" };
const p43 = { id: 43, dueno: "ana", deposito: "norte", estado: "pendiente" };
const p42 = { id: 42, dueno: "marta", deposito: "sur", estado: "pendiente" };

const casos = [
  [marta, "pedido:leer", p42], [marta, "pedido:leer", p41], [marta, "pedido:borrar", p42],
  [lucho, "pedido:leer", p41], [lucho, "pedido:leer", p42], [lucho, "pedido:borrar", p41], [lucho, "pedido:borrar", p43],
  [dani, "pedido:borrar", p41], [dani, "pedido:exportar", p41],
];
for (const [u, a, p] of casos) {
  console.log(`${u.id.padEnd(6)} ${a.padEnd(15)} pedido ${p.id} (${p.estado}, ${p.deposito}) -> ${puede(u, a, p) ? "SI" : "no"}`);
}

create role app_user nologin;
create function mi_usuario() returns text language sql stable
  as $$ select current_setting('app.usuario', true) $$;
create table pedidos (id int primary key, dueno text, cliente text, bultos int);
insert into pedidos values (41,'ana','Ferreteria Norte',3), (42,'marta','Kiosco Sur',12), (43,'ana','Libreria Centro',5);
grant select, insert, update, delete on pedidos to app_user;
grant execute on function mi_usuario() to app_user;
alter table pedidos enable row level security;

set role app_user;
set app.usuario = 'marta';
\echo '-- 1. RLS prendida y ninguna politica:'
select count(*) as filas_visibles from pedidos;
reset role;

create policy cada_uno_lo_suyo on pedidos to app_user using (dueno = mi_usuario());

set role app_user;
set app.usuario = 'marta';
