create table miembros (grupo int, usuario text, rol text, primary key (grupo, usuario));
insert into miembros values (1,'lia','lider'), (1,'beto','ayudante'), (1,'caro','miembro');
grant select, update on miembros to app_user;
alter table miembros enable row level security;

create function soy_lider(g int) returns boolean language sql security definer stable as $$
  select exists (select 1 from miembros
                 where grupo = g and usuario = mi_usuario() and rol in ('lider','ayudante')) $$;
grant execute on function soy_lider(int) to app_user;

create policy ver_el_grupo on miembros for select to app_user using (true);
create policy el_lider_cambia_roles on miembros for update to app_user using (soy_lider(grupo));

set role app_user;
set app.usuario = 'beto';
\echo '-- beto, que es ayudante, se nombra lider y baja a lia:'
update miembros set rol = 'lider' where usuario = 'beto';
update miembros set rol = 'miembro' where usuario = 'lia';
reset role;
select usuario, rol from miembros order by usuario;

drop policy el_lider_cambia_roles on miembros;
revoke update on miembros from app_user;

create function cambiar_rol(g int, u text, r text) returns void language plpgsql security definer as $$
begin
  if not exists (select 1 from miembros where grupo = g and usuario = mi_usuario() and rol = 'lider')
    then raise exception 'solo_lider'; end if;
  update miembros set rol = r where grupo = g and usuario = u;
end $$;
grant execute on function cambiar_rol(int, text, text) to app_user;

set role app_user;
set app.usuario = 'beto';
select cambiar_rol(1, 'beto', 'lider');
set app.usuario = 'lia';
select cambiar_rol(1, 'caro', 'ayudante');
